example:
// shop/fulfil.bynk
context shop.fulfil

actor FromOrders = Producer where IsContext(shop.orders)   // ✗ `shop.orders` declares no `Queue` for `order-events`

service fulfil from queue("order-events") {
  delivery { deadLetter: None }
  on message(order: Order) -> Effect[QueueResult] by FromOrders { … }
}

// shop/orders.bynk
context shop.orders

consumes bynk.cloudflare { Queue }

capability OrderEvents = Queue @name("order-events")   // ✓ a producer of the queue
